```java
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.HashMap;
import java.util.Map;

public class XmlToJsonConverter {

    public static String convertXmlToJson(String xmlInput) throws ParserConfigurationException, IOException, SAXException {
        // Parse XML
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        InputSource is = new InputSource(new StringReader(xmlInput));
        Document doc = builder.parse(is);

        // Convert XML to Map
        Map<String, Object> map = xmlToMap(doc.getDocumentElement());

        // Convert Map to JSON
        return mapToJson(map);
    }

    private static Map<String, Object> xmlToMap(Element element) {
        Map<String, Object> map = new HashMap<>();
        NodeList children = element.getChildNodes();

        for (int i = 0; i < children.getLength(); i++) {
            Node node = children.item(i);
            if (node instanceof Element) {
                Element childElement = (Element) node;
                if (map.containsKey(childElement.getTagName())) {
                    // Handle multiple elements with the same tag name
                    Object existingValue = map.get(childElement.getTagName());
                    if (existingValue instanceof List) {
                        ((List<Object>) existingValue).add(xmlToMap(childElement));
                    } else {
                        List<Object> list = new ArrayList<>();
                        list.add(existingValue);
                        list.add(xmlToMap(childElement));
                        map.put(childElement.getTagName(), list);
                    }
                } else {
                    map.put(childElement.getTagName(), xmlToMap(childElement));
                }
            }
        }

        // Add text content if available
        if (element.getTextContent() != null && !element.getTextContent().trim().isEmpty()) {
            map.put("#text", element.getTextContent().trim());
        }

        // If map contains only one key "#text", return the value directly
        if (map.size() == 1 && map.containsKey("#text")) {
            return (String) map.get("#text");
        }

        return map;
    }

    private static String mapToJson(Map<String, Object> map) throws IOException {
        Gson gson = new GsonBuilder().setPrettyPrinting().create();
        StringWriter writer = new StringWriter();
        gson.toJson(map, writer);
        return writer.toString();
    }

    public static void main(String[] args) {
        String xmlInput = "<patient><name>John Doe</name><age>30</age><symptoms><symptom>Fever</symptom><symptom>Cough</symptom></symptoms></patient>";
        try {
            String jsonOutput = convertXmlToJson(xmlInput);
            System.out.println(jsonOutput);
        } catch (ParserConfigurationException | SAXException | IOException e) {
            e.printStackTrace();
        }
    }
}
```

**Dependencies:**

*   Gson library for JSON serialization (add to your project using Maven or Gradle).

**Example XML Input:**

```xml
<patient>
    <name>John Doe</name>
    <age>30</age>
    <symptoms>
        <symptom>Fever</symptom>
        <symptom>Cough</symptom>
    </symptoms>
</patient>
```

**Example JSON Output:**

```json
