const int SEPSIS_THRESHOLD = 7; // TriHealth internal threshold
const std::string GUIDELINE_REF = "TRI-PROTO-001"; // Example guideline reference

// Patient class to hold symptoms, vitals, and other data
class Patient {
public:
    std::string name;
    int age;
    std::vector<std::string> symptoms;
    std::map<std::string, double> vitals; // e.g., {"temperature", 38.5}
    int sepsisRiskScore;

    Patient(std::string n, int a, std::vector<std::string> s, 
            std::map<std::string, double> v, int sepsisScore)
        : name(n), age(a), symptoms(s), vitals(v), sepsisRiskScore(sepsisScore) {}
};

// Triage system class
class TriageSystem {
public:
    std::string classifyUrgency(const Patient& patient) {
        if (patient.sepsisRiskScore >= SEPSIS_THRESHOLD) {
            return "Immediate ER Referral";
        } else if (patient.vitals.find("temperature") != patient.vitals.end() && 
                   patient.vitals.at("temperature") > 38.0) {
            return "Urgent";
        } else {
            return "Stable";
        }
    }

    std::vector<std::string> suggestOrders(const Patient& patient) {
        std::vector<std::string> orders;
        if (patient.sepsisRiskScore >= 5) {
            orders.push_back("CBC with differential");
            orders.push_back("Blood cultures");
        }
        if (patient.vitals.find("temperature") != patient.vitals.end() && 
            patient.vitals.at("temperature") > 38.0) {
            orders.push_back("Chest X-ray");
        }
        return orders;
    }

    void draftDischargeInstructions(const Patient& patient) {
        if (classifyUrgency(patient) == "Stable") {
            std::cout << "Discharge Instructions for " << patient.name << ":\n";
            std::cout << "1. Monitor symptoms at home.\n";
            std::cout << "2. Follow up with primary care physician within 7 days.\n";
            std::cout << "3. Take prescribed medications as directed.\n";
        } else {
            std::cout << "Patient requires further evaluation before discharge.\n";
        }
    }
};

int main() {
