    std::vector<std::string> symptoms = {"fever", "chills", "fatigue"};
    std::map<std::string, double> vitals = {{"temperature", 38.9}, {"heart_rate", 95}};
    Patient patient("John Doe", 45, symptoms, vitals, 6);

