    int sum = 0;
    for (int i = 0; i < size; ++i) {
        sum += arr[i];
    }
    return sum;
}

// Function to find the maximum value in the array
int findMax(const int arr[], int size) {
    // Using std::max_element for simplicity
    return *std::max_element(arr, arr + size);
}

int main() {
