```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class CustomerDataRetriever {

    // Database credentials (these should be stored securely, e.g., in environment variables)
    private static final String DB_URL = "jdbc:mysql://your_database_url:3306/your_database_name";
    private static final String DB_USER = "your_database_user";
    private static final String DB_PASSWORD = "your_database_password";

    public static void main(String[] args) {
        int customerId = 12345; // Example customer ID
        retrieveCustomerData(customerId);
    }

    public static void retrieveCustomerData(int customerId) {
        Connection connection = null;
        PreparedStatement preparedStatement = null;
        ResultSet resultSet = null;

        try {
            // Establish database connection
            connection = DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);

            // Prepare SQL query with parameterized customer ID
            String sql = "SELECT * FROM customers WHERE customer_id = ?";
            preparedStatement = connection.prepareStatement(sql);
            preparedStatement.setInt(1, customerId);

            // Execute query
            resultSet = preparedStatement.executeQuery();

            // Process results
            if (resultSet.next()) {
                int id = resultSet.getInt("customer_id");
                String name = resultSet.getString("customer_name");
                String email = resultSet.getString("customer_email");

                System.out.println("Customer ID: " + id);
                System.out.println("Name: " + name);
                System.out.println("Email: " + email);
            } else {
                System.out.println("No customer found with ID: " + customerId);
            }

        } catch (SQLException e) {
            System.err.println("Error retrieving customer data: " + e.getMessage());
        } finally {
            // Close resources to prevent leaks
            try {
                if (resultSet != null) resultSet.close();
                if (preparedStatement != null) preparedStatement.close();
                if (connection != null) connection.close();
            } catch (SQLException e) {
                System.err.println("Error closing resources: " + e.getMessage());
            }
        }
    }
}
```

### Key Points:
1. **Database Connection**: Uses `DriverManager.getConnection()` to establish a connection to the SQL database.
2. **Parameterized Query**: Uses `PreparedStatement` to prevent SQL injection by parameterizing the customer ID.
3. **Resource Management**: Ensures proper closure of database resources (`Connection`, `PreparedStatement`, `ResultSet`) in the `finally` block to avoid leaks.
4. **Error Handling**: Catches `SQLException` to handle database-related errors gracefully.

### Notes:
- Replace placeholders (`your_database_url`, `your_database_name`, `your_database_user`, `your_database_password`) with actual database credentials.
- Ensure the MySQL JDBC driver (`mysql-connector-java`) is included in your project's dependencies.

This code adheres to best practices for database interaction in Java and is tailored to retrieve customer data based on a specific customer ID.

