    return output;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        cerr << "Usage: " << argv[0] << " <input.csv> <output.json>" << endl;
        return 1;
    }

    ifstream inputFile(argv[1]);
    ofstream outputFile(argv[2]);

    if (!inputFile || !outputFile) {
        cerr << "Error opening files." << endl;
        return 1;
    }

    Json::Value root;
    string line;
    // Skip header line
    getline(inputFile, line);

    while (getline(inputFile, line)) {
        vector<string> fields = splitCSVLine(line);
        if (fields.size() < 7) continue; // Skip malformed lines

        PatientData patient;
        patient.patientId = fields[0];
        patient.age = stoi(fields[1]);
        patient.temperature = stod(fields[2]);
        patient.heartRate = stoi(fields[3]);
        patient.respiratoryRate = stoi(fields[4]);
        patient.sepsisScore = stoi(fields[5]);

        // Parse medications (comma-separated in CSV)
        string meds = fields[6];
        stringstream medsStream(meds);
