        root["patients"].append(patientOutput);
    }

    // Write JSON output
    Json::StreamWriterBuilder writer;
    string jsonOutput = Json::writeString(writer, root);
    outputFile << jsonOutput;

    cout << "Processing complete. Output saved to " << argv[2] << endl;
    return 0;
}
```

**Key Features:**
